// Brand kit SVGs imported as static images (brand/, used by the landing page).
// next-env.d.ts normally declares image imports, but it is generated by the
// Next compiler and gitignored, and CI typechecks before any build runs.
declare module "@/brand/*.svg" {
  const content: import("next/image").StaticImageData;
  export default content;
}

// Product pictures on the landing page (components/landing/shots/).
declare module "@/components/landing/shots/*.webp" {
  const content: import("next/image").StaticImageData;
  export default content;
}
